template.schema:
interface Input {
  clauseText: string;
  /** Who is asking — affects what risks to highlight. */
  reviewingParty: shared.Party;
}

interface Output {
  plainEnglishSummary: string;
  potentialRisks: string[];
  /** Whether the clause is standard or unusual. */
  assessment: "standard" | "unusual" | "redFlag";
}
